103	export function SchoolSettingsPage() {
104	  const orgId = useOrgId();
105	  const { managedSchool } = useAuth();
106	  const navigate = useNavigate();
107	  const [settings, setSettings] = useState<SchoolSettings>(defaultSettings);
108	  const [loading, setLoading] = useState(true);
109	  const [saving, setSaving] = useState(false);
110	  const [dirty, setDirty] = useState(false);
111	
112	  const fetchSettings = useCallback(async () => {
113	    if (!managedSchool) return;
114	    setLoading(true);
115	    try {
116	      const res = await fetch(
117	        `${API_BASE}/schools/${managedSchool.id}/settings`,
118	        { credentials: 'include' },
119	      );
120	      const data = await safeJson(res);
121	      if (!res.ok) throw new Error(getApiError(data));
122	      if (data.settings && Object.keys(data.settings).length > 0) {
123	        setSettings({ ...defaultSettings, ...data.settings });
124	      } else {
125	        setSettings({ ...defaultSettings, schoolId: managedSchool.id });
126	      }
127	      setDirty(false);
128	    } catch (err: unknown) {
129	      console.error('Error fetching settings:', err);
130	      toast.error(`Failed to load settings: ${(err as Error).message}`);
131	    } finally {
132	      setLoading(false);
133	    }
134	  }, [managedSchool]);
135	
136	  useEffect(() => {
137	    fetchSettings();
138	  }, [fetchSettings]);
139	
140	  const update = (key: string, value: any) => {
141	    setSettings((prev) => ({ ...prev, [key]: value }));
142	    setDirty(true);
143	  };
144	
145	  const handleSave = async () => {
146	    if (!managedSchool) return;
147	    setSaving(true);
148	    try {
149	      const res = await fetch(
150	        `${API_BASE}/schools/${managedSchool.id}/settings`,
151	        {
152	          method: 'PUT',
153	          headers,
154	          credentials: 'include',
155	          body: JSON.stringify(settings),
156	        },
157	      );
158	      const data = await safeJson(res);
159	      if (!res.ok) throw new Error(getApiError(data));
160	      toast.success('Settings saved successfully');
161	      setDirty(false);
162	    } catch (err: unknown) {
163	      toast.error(`Failed to save settings: ${(err as Error).message}`);
164	    } finally {
165	      setSaving(false);
166	    }
167	  };
168	
169	  if (!managedSchool) {
170	    return (
171	      <div className="flex flex-col items-center justify-center h-[calc(100vh-4rem)] bg-slate-50 p-6">
172	        <div className="w-16 h-16 bg-blue-100 text-blue-600 rounded-full flex items-center justify-center mb-4">
173	          <Plane className="w-8 h-8" />
174	        </div>
175	        <h2 className="text-xl font-bold text-slate-900 mb-2">
176	          No School Selected
177	        </h2>
178	        <p className="text-slate-500 mb-4 text-center max-w-md">
179	          Select a school from the Flight Schools page to manage its settings.
180	        </p>
181	        <Button
182	          onClick={() => navigate('/super-admin/flight-schools')}
183	          className="bg-blue-600 hover:bg-blue-700 text-white gap-2"
184	        >
185	          <Plane className="w-4 h-4" /> Go to Flight Schools
186	        </Button>
187	      </div>
188	    );
189	  }
190	
191	  if (loading) {
192	    return (
193	      <div className="flex items-center justify-center h-[calc(100vh-4rem)] bg-slate-50">
194	        <div className="text-slate-500">Loading settings...</div>
195	      </div>
196	    );
197	  }
198	
199	  return (
200	    <div className="flex flex-col h-[calc(100vh-4rem)] overflow-y-auto bg-slate-50 relative">
201	      <div className="p-6 max-w-[1000px] w-full mx-auto">
202	        <div className="flex justify-between items-start mb-6">
203	          <div className="flex items-center gap-3">
204	            <div className="w-10 h-10 bg-slate-100 text-slate-600 rounded-lg flex items-center justify-center">
205	              <Settings className="w-6 h-6" />
206	            </div>
207	            <div>
208	              <h1 className="text-2xl font-bold text-slate-900">
209	                School Settings
210	              </h1>
211	              <p className="text-slate-500 text-sm mt-0.5">
212	                Configure settings for{' '}
213	                <span className="font-medium text-blue-600">
214	                  {managedSchool.name}
215	                </span>
216	              </p>
217	            </div>
218	          </div>
219	          <div className="flex items-center gap-3">
220	            <Button
221	              variant="outline"
222	              onClick={fetchSettings}
223	              className="gap-2 bg-white text-slate-700 border-slate-200 shadow-sm hover:bg-slate-50"
224	            >
225	              <RefreshCcw className="w-4 h-4" /> Reset
226	            </Button>
227	            <Button
228	              onClick={handleSave}
229	              disabled={!dirty || saving}
230	              className="gap-2 bg-blue-600 hover:bg-blue-700 text-white shadow-sm disabled:opacity-50"
231	            >
232	              <Save className="w-4 h-4" />{' '}
233	              {saving ? 'Saving...' : 'Save Settings'}
234	            </Button>
235	          </div>
236	        </div>
237	
238	        {dirty && (
239	          <div className="bg-amber-50 border border-amber-200 rounded-lg px-4 py-2.5 mb-6 text-sm text-amber-800 flex items-center gap-2">
240	            <div className="w-2 h-2 rounded-full bg-amber-500 animate-pulse" />
241	            You have unsaved changes
242	          </div>
243	        )}
244	
245	        <div className="space-y-6">
246	          {/* General */}
247	          <SettingCard title="General" icon={<Globe className="w-4 h-4" />}>
248	            <div className="grid grid-cols-3 gap-4">
249	              <div>
250	                <label className="block text-sm font-medium text-slate-700 mb-1.5">
251	                  Timezone
252	                </label>
253	                <select
254	                  value={settings.timezone}
255	                  onChange={(e) => update('timezone', e.target.value)}
256	                  className="w-full border border-slate-200 rounded-lg px-3 py-2 text-sm text-slate-700 bg-white outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent"
257	                >
