35	function groupConsecutiveEntries(
36	  entries: LocationAuditEntry[],
37	): GroupedLocationAuditEntry[] {
38	  const result: GroupedLocationAuditEntry[] = [];
39	  for (const entry of entries) {
40	    const prev = result.at(-1);
41	    if (
42	      prev &&
43	      prev.action === entry.action &&
44	      prev.details === entry.details
45	    ) {
46	      prev.groupCount += 1;
47	    } else {
48	      result.push({ ...entry, groupCount: 1 });
49	    }
50	  }
51	  return result;
52	}
