140	function formatTimestamp(ts: string) {
141	  const d = new Date(ts);
142	  const now = new Date();
143	  const diffMs = now.getTime() - d.getTime();
144	  const diffH = diffMs / (1000 * 60 * 60);
145	  if (diffH < 1) return `${Math.max(1, Math.floor(diffMs / 60000))}m ago`;
146	  if (diffH < 24) return `${Math.floor(diffH)}h ago`;
147	  if (diffH < 48) return 'Yesterday';
148	  return d.toLocaleDateString('en-US', {
149	    month: 'short',
150	    day: 'numeric',
151	    year: 'numeric',
152	  });
153	}
