279	function calculateCourseDuration(course: AvailableTrainingCourse) {
280	  const storedWeeks = Number.parseInt(
281	    String(course.defaultDuration || '').replace(/[^0-9]/g, ''),
282	    10,
283	  );
284	  if (storedWeeks > 0) return storedWeeks;
