92	function getTimeAgo(timestamp: string): string {
93	  const now = new Date();
94	  const then = new Date(timestamp);
95	  const diffMs = now.getTime() - then.getTime();
96	  const diffMin = Math.floor(diffMs / 60000);
97	  const diffH = Math.floor(diffMs / 3600000);
98	  const diffD = Math.floor(diffMs / 86400000);
99	  if (diffMin < 1) return 'Just now';
100	  if (diffMin < 60) return `${diffMin}m ago`;
101	  if (diffH < 24) return `${diffH}h ago`;
102	  if (diffD === 1) return 'Yesterday';
103	  if (diffD < 7) return `${diffD} days ago`;
104	  return then.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
105	}
